class ParallelSlotsAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.spy = self.AddEquity("SPY", Resolution.Daily, fill_forward=False).Symbol
        self.aapl = self.AddEquity("AAPL", Resolution.Daily, fill_forward=False).Symbol
        self.ibm = self.AddEquity("IBM", Resolution.Daily, fill_forward=False).Symbol
        self.bac = self.AddEquity("BAC", Resolution.Daily, fill_forward=False).Symbol
        self.aig = self.AddEquity("AIG", Resolution.Daily, fill_forward=False).Symbol

        self.symbols = [self.spy, self.aapl, self.ibm, self.bac, self.aig]

        self.spy_closes = RollingWindow[float](101)
        self.aapl_rsi = self.RSI(
            self.aapl,
            14,
            MovingAverageType.Wilders,
            Resolution.Daily
        )

        self.aapl_previous_close = None
        self.aapl_red_streak = 0

        self.SetWarmUp(101, Resolution.Daily)

    def OnData(self, data: Slice):
        if data.Bars.ContainsKey(self.spy):
            self.spy_closes.Add(data.Bars[self.spy].Close)

        if data.Bars.ContainsKey(self.aapl):
            aapl_close = data.Bars[self.aapl].Close

            if self.aapl_previous_close is not None and aapl_close < self.aapl_previous_close:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0

            self.aapl_previous_close = aapl_close

        if self.IsWarmingUp:
            return

        if not all(data.Bars.ContainsKey(symbol) for symbol in self.symbols):
            return

        if not self.spy_closes.IsReady or not self.aapl_rsi.IsReady:
            return

        spy_close = data.Bars[self.spy].Close
        aapl_close = data.Bars[self.aapl].Close

        current_sma = sum(self.spy_closes[i] for i in range(100)) / 100.0
        previous_sma = sum(self.spy_closes[i] for i in range(1, 101)) / 100.0

        previous_spy_close = self.spy_closes[1]
        spy_crosses_above_sma = (
            previous_spy_close <= previous_sma and spy_close > current_sma
        )
        spy_crosses_below_sma = (
            previous_spy_close >= previous_sma and spy_close < current_sma
        )

        if self.Portfolio[self.spy].Quantity > 0:
            if spy_crosses_below_sma:
                self.Liquidate(self.spy)
        elif spy_crosses_above_sma:
            self.SetHoldings(self.spy, 0.40)

        if self.Portfolio[self.aapl].Quantity > 0:
