        spy_close = float(data.Bars[self.spy].Close)
        aapl_close = float(data.Bars[self.aapl].Close)

        spy_sma_today = sum(self.spy_closes[i] for i in range(100)) / 100.0
        spy_sma_yesterday = sum(self.spy_closes[i] for i in range(1, 101)) / 100.0
        spy_close_yesterday = self.spy_closes[1]

        spy_crosses_above = (
            spy_close_yesterday <= spy_sma_yesterday and
            spy_close > spy_sma_today
        )
        spy_crosses_below = (
            spy_close_yesterday >= spy_sma_yesterday and
            spy_close < spy_sma_today
        )

        # Slot 1: Strategy A
        if self.strategy_a_lot > 0:
            if spy_crosses_below:
                self.MarketOrder(self.spy, -self.strategy_a_lot)
        elif spy_crosses_above:
            target_value = 0.40 * self.Portfolio.TotalPortfolioValue
            quantity = int(target_value // spy_close)
            if quantity > 0:
                self.MarketOrder(self.spy, quantity)

        # Slot 2: Strategy B
        if self.strategy_b_lot > 0:
            if self.aapl_rsi.Current.Value > 60:
                self.MarketOrder(self.aapl, -self.strategy_b_lot)
        elif self.aapl_red_streak >= 3:
            if self.Portfolio.Cash >= 20_000:
                quantity = int(20_000 // aapl_close)
                if quantity > 0:
                    self.MarketOrder(self.aapl, quantity)

    def OnOrderEvent(self, order_event: OrderEvent):
        if order_event.Status != OrderStatus.Filled:
            return

        if order_event.Symbol == self.spy:
            self.strategy_a_lot += order_event.FillQuantity
        elif order_event.Symbol == self.aapl:
            self.strategy_b_lot += order_event.FillQuantity
